<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ExportOutlined as ExternalLinkOutlined, ExperimentOutlined as SparklesOutlined, FilterOutlined, ReloadOutlined, SendOutlined } from '@ant-design/icons-vue'
import { message } from 'ant-design-vue'
import { aiApi, monitoredUsersApi, qqApi, tweetsApi } from '@/services/api'; import { getErrorMessage } from '@/services/http'; import type { MonitoredUser, QQBotAccount, QQJoinedGroup, Tweet } from '@/types'; import { formatDateTime, formatNumber, formatRelative, tweetTime } from '@/utils/format'; import PageHeader from '@/components/PageHeader.vue'
const tweets = ref<Tweet[]>([]); const accounts = ref<MonitoredUser[]>([]); const total = ref(0); const loading = ref(false); const selected = ref<number[]>([]); const generating = ref<string | null>(null); const pushOpen = ref(false); const sending = ref(false); const bots = ref<QQBotAccount[]>([]); const groups = ref<QQJoinedGroup[]>([]); const pushForm = reactive({ bot_id: null as number | null, group_openids: [] as string[] }); const filters = reactive({ page: 1, page_size: 15, search: '', monitored_user_id: '', date_from: '', date_to: '' })
const hasFilters = computed(() => Boolean(filters.search || filters.monitored_user_id || filters.date_from || filters.date_to))
async function load() { loading.value = true; try { const result = await tweetsApi.list({ page: filters.page, page_size: filters.page_size, search: filters.search || undefined, monitored_user_id: filters.monitored_user_id || undefined, posted_after: filters.date_from ? `${filters.date_from}T00:00:00Z` : undefined, posted_before: filters.date_to ? `${filters.date_to}T23:59:59Z` : undefined }); tweets.value = result.items; total.value = result.total } catch (e) { message.error(getErrorMessage(e, '无法加载内容流')) } finally { loading.value = false } }
function clear() { filters.search = ''; filters.monitored_user_id = ''; filters.date_from = ''; filters.date_to = '' }
async function openPush() { try { bots.value = await qqApi.bots(); pushForm.bot_id = bots.value.find((bot) => bot.is_enabled)?.id || null; groups.value = pushForm.bot_id ? await qqApi.joinedGroups(pushForm.bot_id) : []; pushForm.group_openids = []; pushOpen.value = true } catch (e) { message.error(getErrorMessage(e, '无法读取 QQ 账号')) } }
async function changeBot() { pushForm.group_openids = []; groups.value = pushForm.bot_id ? await qqApi.joinedGroups(pushForm.bot_id) : [] }
async function sendBatch() { if (!pushForm.bot_id || !pushForm.group_openids.length) return message.warning('请选择机器人和发送群'); sending.value = true; try { const result = await qqApi.batchPush({ bot_id: pushForm.bot_id, group_openids: pushForm.group_openids, tweet_ids: selected.value }); message.success(result.message); pushOpen.value = false; selected.value = [] } catch (e) { message.error(getErrorMessage(e, 'QQ 推送失败')) } finally { sending.value = false } }
async function generate(tweet: Tweet) { generating.value = String(tweet.id); try { await aiApi.generateFromTweet(tweet.tweet_id, { idempotency_key: globalThis.crypto?.randomUUID?.() || `${Date.now()}-${tweet.tweet_id}` }); message.success('AI 创作任务已提交') } catch (e) { message.error(getErrorMessage(e, '无法创建 AI 任务')) } finally { generating.value = null } }
onMounted(async () => { void load(); try { accounts.value = (await monitoredUsersApi.list({ page: 1, page_size: 100 })).items } catch {} }); watch(() => [filters.monitored_user_id, filters.date_from, filters.date_to], () => { filters.page = 1; void load() })
</script>

<template><div class="page-stack"><PageHeader eyebrow="MONITOR / 02" title="内容流" description="检索采集内容，并将内容送往创作或推送流程"><template #actions><a-button :disabled="!selected.length" type="primary" @click="openPush"><SendOutlined /> QQ 批量推送（{{ selected.length }}）</a-button></template></PageHeader><a-card :bordered="false"><div class="toolbar"><div class="toolbar__controls"><a-input v-model:value="filters.search" placeholder="搜索正文、用户名或关键词" allow-clear style="width:250px" @press-enter="load" /><a-select v-model:value="filters.monitored_user_id" allow-clear placeholder="全部账号" style="width:160px" :options="accounts.map((item) => ({ label:`@${item.username}`, value:String(item.id) }))" /><a-input v-model:value="filters.date_from" type="date" style="width:140px" /><a-input v-model:value="filters.date_to" type="date" style="width:140px" /><a-button @click="clear"><FilterOutlined /> 清空</a-button><a-button @click="load"><ReloadOutlined /></a-button></div><span class="toolbar__hint">{{ hasFilters ? '已应用筛选' : '全部采集内容' }} · 共 {{ total }} 条</span></div><a-table :data-source="tweets" :loading="loading" :row-selection="{ selectedRowKeys:selected, onChange:(keys: any[]) => selected = keys as number[] }" :pagination="{ current: filters.page, pageSize: filters.page_size, total, showSizeChanger:false }" row-key="id" @change="(page: any) => { filters.page = page.current; load() }"><a-table-column title="内容" key="text" :width="420"><template #default="{ record }"><div><strong>@{{ record.username }}</strong><p style="margin:5px 0;color:var(--ink);white-space:pre-wrap">{{ record.text }}</p><span class="muted">{{ formatRelative(tweetTime(record)) }} · {{ record.lang || '—' }}</span></div></template></a-table-column><a-table-column title="互动"><template #default="{ record }"><span class="mono">赞 {{ formatNumber(record.like_count) }} · 转 {{ formatNumber(record.retweet_count) }}</span></template></a-table-column><a-table-column title="采集时间"><template #default="{ record }"><span class="muted">{{ formatDateTime(record.fetched_at) }}</span></template></a-table-column><a-table-column title="操作" width="190"><template #default="{ record }"><a-space><a-button type="link" size="small" :loading="generating === String(record.id)" @click="generate(record)"><SparklesOutlined /> AI 生成</a-button><a :href="`https://x.com/${record.username}/status/${record.tweet_id}`" target="_blank" rel="noreferrer"><a-button type="text" size="small"><ExternalLinkOutlined /></a-button></a></a-space></template></a-table-column></a-table></a-card><a-modal v-model:open="pushOpen" title="批量推送到 QQ" ok-text="提交推送" cancel-text="取消" :confirm-loading="sending" @ok="sendBatch"><a-form layout="vertical"><a-form-item label="QQ 机器人"><a-select v-model:value="pushForm.bot_id" :options="bots.map((bot) => ({label:bot.name,value:bot.id}))" @change="changeBot" /></a-form-item><a-form-item label="发送群"><a-select v-model:value="pushForm.group_openids" mode="multiple" :options="groups.map((group) => ({label:group.name || group.group_openid,value:group.group_openid}))" /></a-form-item></a-form></a-modal></div></template>
